const clone=x=>JSON.parse(JSON.stringify(x));
function draft(){return {v:1,mode:'manual',race:'human',job:'warrior',rolled:false,offers:[],unique:null,base:Object.fromEntries(stats.map(k=>[k,8])),human:['STR','DEX','CON'],profs:{},weapon:'greatsword',name:''};}
function cost(d){return stats.reduce((n,k)=>n+(prices[d.base[k]-8]??1000),0);}
function profCost(d){return Object.values(d.profs).reduce((n,x)=>n+({D:1,C:3}[x]??1000),0);}
function roll(d,random=Math.random){if(d.rolled)throw Error('สุ่มได้ครั้งเดียวต่อตัวละคร');const out=clone(d),pick=a=>a[Math.min(a.length-1,Math.floor(random()*a.length))];out.race=pick(Object.keys(races));out.job=pick(Object.keys(classes));out.mode='random';out.rolled=true;out.offers=[];let pool=uniques.map(x=>x.id);while(out.offers.length<3){const id=pick(pool);out.offers.push(id);pool=pool.filter(x=>x!==id);}out.unique=null;out.weapon=classes[out.job].starter[0];return out;}
function validateDraft(d){if(!d||d.v!==1||!races[d.race]||!classes[d.job]||!['manual','random'].includes(d.mode)||typeof d.rolled!=='boolean'||!d.base||stats.some(k=>!Number.isInteger(d.base[k])||d.base[k]<8||d.base[k]>15)||cost(d)>27||!d.profs||Array.isArray(d.profs)||Object.entries(d.profs).some(([k,v])=>!profs[k]||!['D','C'].includes(v))||profCost(d)>8||!Array.isArray(d.human)||d.human.length!==3||new Set(d.human).size!==3||d.human.some(k=>!stats.includes(k))||!classes[d.job].starter.includes(d.weapon))throw Error('แต้มสร้างตัวละครหรืออุปกรณ์ไม่ถูกต้อง');if(!Array.isArray(d.offers)||d.rolled&&(d.mode!=='random'||d.offers.length!==3||new Set(d.offers).size!==3||d.offers.some(k=>!uniques.some(u=>u.id===k))||d.unique!==null&&!d.offers.includes(d.unique))||!d.rolled&&(d.mode!=='manual'||d.offers.length||d.unique!==null))throw Error('ผลสุ่มไม่ถูกต้อง');return clone(d);}
function finalStats(d){const out={...d.base},bonus=d.race==='human'?Object.fromEntries(d.human.map(k=>[k,1])):races[d.race].bonus;for(const [k,v] of Object.entries(bonus))out[k]+=v;return out;}
function recommend(d){const out=clone(d),order=[classes[d.job].primary,'CON',...stats].filter((v,i,a)=>a.indexOf(v)===i);order.forEach((k,i)=>out.base[k]=[15,15,13,10,10,8][i]);const weapon=weapons[out.weapon],p=profs[weapon.type]?weapon.type:'arcane';out.profs={[p]:'C',survival:'D',perception:'D'};const extra=d.job==='knight'?'shield':d.job==='priest'?'healing':d.job==='alchemist'?'alchemy':d.job==='mage'?'fire':'light';out.profs[extra]='C';return out;}
function build(d,name){d=validateDraft(d);if(typeof name!=='string'||!name.trim()||name.trim().length>30)throw Error('ตั้งชื่อ 1–30 ตัวอักษร');if(d.rolled&&!d.unique)throw Error('เลือก Unique หนึ่งสกิลก่อน');return {name:name.trim(),race:d.race,job:d.job,level:1,xp:0,stats:finalStats(d),design:1,creation:d,unique:d.unique,skills:[...classes[d.job].skills],proficiencyGrades:{...d.profs},practice:{},equipment:{main:d.weapon,off:d.job==='knight'?'shield':null,armor:classes[d.job].armor},inventory:{potions:d.job==='alchemist'?5:3,reagents:3,weapons:[d.weapon]},duelTrials:0};}
function equip(c,main,off=null){const a=weapons[main],b=off==='shield'?null:weapons[off],job=classes[c.job];if(!a||!job||!job.weapons.includes(a.type)||c.level<a.level||off&&a.hands===2||off&&off!=='shield'&&(!b||b.hands!==1||!job.weapons.includes(b.type)||c.level<b.level)||off==='shield'&&c.job!=='knight'||b&&!c.proficiencyGrades?.dual)throw Error('คลาส เลเวล หรือความชำนาญอาวุธคู่ไม่ผ่าน');const owned=c.inventory?.weapons||[];if(!owned.includes(main)||b&&(!owned.includes(off)||main===off&&owned.filter(k=>k===main).length<2))throw Error('ไม่มีอาวุธครบทั้งสองชิ้นในกระเป๋า');return {...c.equipment,main,off};}
function gain(c,key,n){if(!profs[key]&&key!=='dual')return;c.practice??={};c.proficiencyGrades??={};c.practice[key]=(c.practice[key]||0)+n*(c.unique==='talent'?2:1);const grade=c.proficiencyGrades[key];if(!grade&&c.practice[key]>=20)c.proficiencyGrades[key]='D';if(c.proficiencyGrades[key]==='D'&&c.practice[key]>=100)c.proficiencyGrades[key]='C';/* B–S require explicit trials; never auto-promote. */}
function validateCharacter(c){if(c.design!==1)return c;validateDraft(c.creation);if(!classes[c.job]||!races[c.race]||stats.some(k=>!Number.isInteger(c.stats[k])||c.stats[k]<1||c.stats[k]>99)||c.unique!==c.creation.unique||c.job!==c.creation.job||c.race!==c.creation.race||!Array.isArray(c.skills)||c.skills.some(k=>!skills[k])||classes[c.job].skills.some(k=>!c.skills.includes(k))||!c.proficiencyGrades||Object.entries(c.proficiencyGrades).some(([k,v])=>(!profs[k]&&k!=='dual')||!['D','C','B','A','S'].includes(v))||!c.practice||Object.values(c.practice).some(n=>!Number.isFinite(n)||n<0)||!c.inventory||!Array.isArray(c.inventory.weapons)||c.inventory.weapons.length>100||c.inventory.weapons.some(k=>!weapons[k])||['potions','reagents'].some(k=>!Number.isInteger(c.inventory[k])||c.inventory[k]<0||c.inventory[k]>999))throw Error('ข้อมูลตัวละครรุ่นใหม่ไม่ถูกต้อง');equip(c,c.equipment?.main,c.equipment?.off);return c;}
const maxHp=c=>60+4*c.stats.CON;
const api={maxHp,stats,prices,races,classes,skills,uniques,profs,weapons,draft,cost,profCost,roll,validateDraft,finalStats,recommend,build,equip,gain,validateCharacter};g.DecideCreation=api;if(typeof module!=='undefined')module.exports=api;
